import * as React from "react"

function GamingProfile({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="gaming-profile"
      className={className}
      {...props}
    >

        <div className="max-w-xs bg-gray-800 rounded-2xl shadow-lg overflow-hidden border border-gray-700">

          <img className="w-full h-48 object-cover" src="https://i.pravatar.cc/300?img=12" alt="Player Avatar" />


          <div className="p-5 text-center">
            <h2 className="text-xl font-bold text-white">BONIMATER</h2>
            <p className="text-sm text-gray-400">Level 45 | Warrior</p>


            <div className="mt-4 flex gap-2 justify-center">
              <button className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-sm">Add Friend</button>
              <button className="px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg text-sm">Message</button>
            </div>
          </div>
        </div>
    </div>
  )
}

export { GamingProfile }
